BEGIN IMMEDIATE;
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,path TEXT NOT NULL UNIQUE,brief TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL);
CREATE TABLE threads(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id),title TEXT NOT NULL,draft TEXT NOT NULL DEFAULT '',layout TEXT NOT NULL DEFAULT 'focus',session_id TEXT,created_at INTEGER NOT NULL);
CREATE INDEX threads_project ON threads(project_id,created_at);
CREATE TABLE runs(id TEXT PRIMARY KEY,command_id TEXT NOT NULL UNIQUE,thread_id TEXT NOT NULL REFERENCES threads(id),workspace TEXT NOT NULL,lease_key TEXT NOT NULL,prompt TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','starting','running','waiting','cancelling','completed','cancelled','failed','interrupted','unknown')),session_id TEXT,error TEXT,usage TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL);
CREATE INDEX runs_status ON runs(status,created_at);
CREATE TABLE receipts(command_id TEXT PRIMARY KEY,run_id TEXT NOT NULL UNIQUE REFERENCES runs(id),thread_id TEXT NOT NULL REFERENCES threads(id),prompt TEXT NOT NULL);
CREATE TABLE leases(workspace TEXT PRIMARY KEY,run_id TEXT NOT NULL UNIQUE REFERENCES runs(id));
CREATE TABLE messages(sequence INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT NOT NULL UNIQUE,thread_id TEXT NOT NULL REFERENCES threads(id),run_id TEXT REFERENCES runs(id),role TEXT NOT NULL,body TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX messages_thread ON messages(thread_id,sequence);
CREATE TABLE output_chunks(run_id TEXT NOT NULL REFERENCES runs(id),role TEXT NOT NULL CHECK(role IN ('assistant','tool')),offset INTEGER NOT NULL CHECK(offset>=0),body TEXT NOT NULL,byte_length INTEGER NOT NULL CHECK(byte_length>0 AND byte_length<=65536),PRIMARY KEY(run_id,role,offset));
CREATE TABLE notes(id TEXT PRIMARY KEY,thread_id TEXT NOT NULL REFERENCES threads(id),message_id TEXT REFERENCES messages(id),body TEXT NOT NULL,pinned INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX notes_thread ON notes(thread_id);
CREATE TABLE templates(id TEXT PRIMARY KEY,title TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE activities(id INTEGER PRIMARY KEY AUTOINCREMENT,thread_id TEXT NOT NULL REFERENCES threads(id),kind TEXT NOT NULL,summary TEXT NOT NULL,source_id TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX activities_thread ON activities(thread_id,id);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings(key,value) VALUES('app','{"theme":"paper","grok_path":"","max_active_runs":4}');
PRAGMA user_version=2;
COMMIT;
